/**
 * WORLD PACK V2 (thème « monde ») — données pures, AUCUN import (partagé avec convex/cardsCatalog.ts).
 * GÉNÉRÉ par scripts/make-monde-v2.py (ne pas éditer à la main) depuis Tri-etoiles-monde_2.xlsx (« Étoiles finales (VALIDÉ) »).
 * 5240 cartes · 36 sous-thèmes, regroupés à l'affichage en 6 (14 Merveilles · Ardèche · Lieux & pays · Animaux ·
 * Nourriture · Voitures). Les cartes de la V1 gardent leur identifiant et leur illustration (scripts/data/monde-ids.json).
 * Les 14 Merveilles restent SECRÈTES (diorama 3D).
 */
export type MondeRarity = 'common' | 'uncommon' | 'rare' | 'epic' | 'legendary' | 'mythic' | 'secret';

export interface MondeSub {
  id: string;
  label: string;
  code: string;
  /** groupe d'affichage (lieux, animaux, nourriture, voitures) ; absent = sous-thème seul (Merveilles, Ardèche) */
  group?: string;
}

export interface MondeEntry {
  /** identifiant de carte — ne JAMAIS le changer */
  id: string;
  sub: string;
  num: number;
  name: string;
  rarity: MondeRarity;
  /** dossier de l'illustration (art/monde, ou l'ancien dossier V1) */
  dir: string;
  /** fichier dans `dir` ('' = aucune illustration : design typographique) */
  file: string;
  /** 'c' image pleine · 'i' détourée · '' aucune */
  art: '' | 'c' | 'i';
  /** type affiché (« Mammifère », « Capitale / Métropole »…) */
  label: string;
}

